    #[test]
    fn final_annotated_name_with_initial_value_succeeds() {
        let mut env = Environment::new();
        check_stmt(
            &mut env,
            &HirStmt::AnnAssign {
                target: "x".to_string(),
                annotation: Ty::Int,
                value: Some(HirExpr::IntLiteral(1)),
                is_final: true,
            },
        )
        .unwrap();
        assert_eq!(env.lookup("x"), Some(Ty::Int));
    }

