    #[test]
    fn match_enum_exhaustive_with_other_class_pattern() {
        // A case pattern with a different class name than the enum subject
        // exercises the guard-false branch of `collect_enum_member_patterns`'s
        // `HirPattern::Class { class_name: cn, .. } if cn == class_name` arm.
        let mut env = Environment::new();
        env.bind_class(
            "Color".to_string(),
            HirClassDef {
                name: "Color".to_string(),
                bases: Vec::new(),
                mro: vec!["Color".to_string()],
                attrs: Vec::new(),
                methods: Vec::new(),
                properties: Vec::new(),
                static_methods: Vec::new(),
                class_methods: Vec::new(),
                type_param: None,
                enum_members: vec![("RED".to_string(), 1), ("GREEN".to_string(), 2)],
                is_dataclass: false,
                dataclass_fields: Vec::new(),
                is_protocol: false,
                runtime_checkable: false,
                protocol_members: Vec::new(),
                abstract_methods: Vec::new(),
                is_abstract: false,
            },
        );
        env.bind_class(
            "Other".to_string(),
            HirClassDef {
                name: "Other".to_string(),
                bases: Vec::new(),
                mro: vec!["Other".to_string()],
                attrs: Vec::new(),
                methods: Vec::new(),
                properties: Vec::new(),
                static_methods: Vec::new(),
                class_methods: Vec::new(),
                type_param: None,
                enum_members: Vec::new(),
                is_dataclass: false,
                dataclass_fields: Vec::new(),
                is_protocol: false,
                runtime_checkable: false,
                protocol_members: Vec::new(),
                abstract_methods: Vec::new(),
                is_abstract: false,
            },
        );
        let cases = vec![
            HirMatchCase {
                pattern: HirPattern::Class {
                    class_name: "Color".to_string(),
                    positional: vec![],
                    keyword: vec![],
                },
                guard: None,
                body: vec![],
            },
            HirMatchCase {
                pattern: HirPattern::Class {
                    class_name: "Color".to_string(),
                    positional: vec![],
                    keyword: vec![],
                },
                guard: None,
                body: vec![],
            },
            HirMatchCase {
                pattern: HirPattern::Class {
                    class_name: "Other".to_string(),
                    positional: vec![],
                    keyword: vec![],
                },
                guard: None,
                body: vec![],
            },
        ];
        assert!(check_exhaustive(
            &env,
            &Ty::Instance(Box::new("Color".to_string())),
            &cases
        ));
    }

